import sqlite3

from langchain_core.tools import tool

DB_PATH = "reservations.db"


@tool
def cancel_reservation_record(reservation_id: str) -> dict:
    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.execute("DELETE FROM reservations WHERE id = ?", (reservation_id,))
        conn.commit()
        deleted = cur.rowcount
    finally:
        conn.close()
    result = {
        "reservation_id": reservation_id,
        "cancelled": deleted > 0,
    }
    if not deleted:
        result["error"] = "Reservation not found"
    return result

import sqlite3

DB_PATH = "reservations.db"


def move_reservation_to_new_table(reservation_id: str, new_table_id: str, new_time: str) -> dict:
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT table_id, reservation_time FROM reservations WHERE id = ?",
            (reservation_id,),
        ).fetchone()
        if row is None:
            return {"success": False, "error": "Reservation not found"}
        conn.execute(
            "UPDATE reservations SET table_id = ?, reservation_time = ? WHERE id = ?",
            (new_table_id, new_time, reservation_id),
        )
        conn.commit()
    finally:
        conn.close()
    return {
        "success": True,
        "reservation_id": reservation_id,
        "old_table_id": row[0],
        "old_time": row[1],
        "new_table_id": new_table_id,
        "new_time": new_time,
    }
